properties.query:
let baselineWindow = 24h;
let alertWindow = 15m;
let gateMultiplier = toscalar(_GetWatchlist('UAV_Threshold_List') | where ThresholdKey == 'VncByteGateMultiplier' | project toreal(Value));
let dynamicBytesGate = toscalar(
    UAVGcsAccess_CL
    | where TimeGenerated > ago(baselineWindow)
    | where Transport == "novnc" and Action == "disconnect"
    | summarize gate = percentile(BytesReceived, 99) * gateMultiplier
);
UAVGcsAccess_CL
| where TimeGenerated > ago(alertWindow)
| where Transport == "novnc" and Action == "disconnect"
| where BytesReceived > dynamicBytesGate
| extend TriggerReason = strcat("VNC세션대량수신의심_", Operator, "_", tostring(BytesReceived), "bytes")
| project TimeGenerated, Operator, ClientIp, SessionId, DurationSec, BytesReceived, BytesSent, TriggerReason
| order by TimeGenerated desc
